queries.query:
with daily as (
  find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
  | aggregate { date_trunc("day", pe.startts) as day, count() as builds }
  | group_by day
)
find daily | aggregate { round(avg(builds), 1) as builds_per_day }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.build_duration > 0
| aggregate { median(pe.build_duration) / 1000.0 as median_duration_s }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| filter pe.moduleinfo_repository is not null and pe.moduleinfo_repository != 'NA' and pe.moduleinfo_repository != ''
| aggregate { distinct_count(pe.moduleinfo_repository) as active_repos }

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate { date_trunc("week", pe.startts) as week, case when pe.status = "SUCCESS" then "Success" when pe.status = "FAILED" then "Failed" when pe.status = "ABORTED" then "Aborted" when pe.status = "EXPIRED" then "Expired" else "Other" end as outcome, count() as builds }
| group_by week, outcome
| order_by week asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate { case when pe.status = "SUCCESS" then "Success" when pe.status = "FAILED" then "Failed" when pe.status = "ABORTED" then "Aborted" when pe.status = "EXPIRED" then "Expired" else "Other" end as outcome, count() as builds }
| group_by outcome
| order_by builds desc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate { date_trunc("week", pe.startts) as week, round(100.0 * count(case when pe.status = "SUCCESS" then 1 end) / nullif(count(), 0), 1) as success_rate_pct }
| group_by week
| order_by week asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate { date_trunc("week", pe.startts) as week, round(sum(pe.build_duration) / 3600000.0, 2) as ci_hours }
| group_by week
| order_by week asc

find view "ci:pipeline_execution_summary_ci" pe | filter pe.startts >= cast(${start_time} as timestamp) and pe.startts <= cast(${end_time} as timestamp) | filter ${project_filter_predicate} and ${pipeline_filter_predicate} and ${repository_filter_predicate}
| aggregate { pe.projectidentifier as project, count() as builds }
| group_by project
| order_by builds desc
| limit 10
